// KPIデータを整形し、達成率を計算
const data = $input.all()[0].json;

// データが取得できなかった場合のフォールバック
if (!data || !data.kpis) {
  return [{
    json: {
      error: true,
      useFallback: true,
      message: "KPI data not available, using fallback"
    }
  }];
}

const kpis = data.kpis;

// 達成率計算
const pvAchievement = ((kpis.pv.current / kpis.pv.target) * 100).toFixed(1);
const cvrAchievement = ((kpis.cvr.current / kpis.cvr.target) * 100).toFixed(1);

// 前日比・前週比計算
const pvChangeYesterday = ((kpis.pv.current - kpis.pv.yesterday) / kpis.pv.yesterday * 100).toFixed(1);
const pvChangeWeek = ((kpis.pv.current - kpis.pv.last_week) / kpis.pv.last_week * 100).toFixed(1);
const cvrChangeYesterday = ((kpis.cvr.current - kpis.cvr.yesterday) / kpis.cvr.yesterday * 100).toFixed(1);

// GPT-4プロンプト用データ
return [{
  json: {
    date: data.date,
    period: data.period,
    // 整形済みKPI
    current_pv: kpis.pv.current.toLocaleString(),
    target_pv: kpis.pv.target.toLocaleString(),
    pv_achievement: pvAchievement,
    current_cvr: kpis.cvr.current,
    target_cvr: kpis.cvr.target,
    cvr_achievement: cvrAchievement,
    line_friends: kpis.line.friends,
    line_open_rate: kpis.line.open_rate,
    line_click_rate: kpis.line.click_rate,
    note_articles: kpis.note.articles,
    top_article_title: kpis.note.top_articles[0]?.title || "N/A",
    top_article_pv: kpis.note.top_articles[0]?.pv || 0,
    top_article_cv: kpis.note.top_articles[0]?.cv || 0,
    sns_posts: kpis.sns.posts,
    sns_engagement: kpis.sns.engagement_rate,
    demo_reservations: kpis.demo.reservations,
    demo_conversions: kpis.demo.conversions,
    conversion_rate: kpis.demo.conversion_rate,
    // 変化率
    pv_change_yesterday: pvChangeYesterday,
    pv_change_week: pvChangeWeek,
    cvr_change_yesterday: cvrChangeYesterday,
    // アラート判定用
    alert_pv_drop: parseFloat(pvChangeYesterday) < -20,
    alert_cvr_drop: parseFloat(cvrChangeYesterday) < -15,
    // 生データも保持
    raw_data: kpis
  }
}];

// GPT-4のレポートをパースし、改善提案を抽出
const input = $input.all()[0].json;

// GPT-4が失敗した場合のフォールバック
if (!input.choices || !input.choices[0]) {
  const fallbackReport = `# 📊 日次レポート - ${$('データ整形').item.json.date}\n\n## ⚠️ システムエラー\n\nGPT-4 APIが一時的に利用できません。\n\n### 基本KPI\n- PV: ${$('データ整形').item.json.current_pv} (${$('データ整形').item.json.pv_achievement}%)\n- CVR: ${$('データ整形').item.json.current_cvr}% (${$('データ整形').item.json.cvr_achievement}%)\n\n詳細な分析は次回レポートで提供されます。`;

  return [{
    json: {
      report_markdown: fallbackReport,
      proposals: [],
      auto_executable: [],
      manual_required: [],
      is_fallback: true,
      generated_at: new Date().toISOString(),
      kpi_data: $('データ整形').item.json
    }
  }];
}

const report = input.choices[0].message.content;

// 改善提案を抽出（正規表現）
const proposalRegex = /### 提案(\d+):\s*(.+?)\n-\s*期待効果:\s*(.+?)\n-\s*実行難易度:\s*(.+?)\n-\s*推奨実施時期:\s*(.+?)\n-\s*自動実行:\s*(.+)/g;
const proposals = [];
let match;

while ((match = proposalRegex.exec(report)) !== null) {
  proposals.push({
    number: parseInt(match[1]),
    title: match[2].trim(),
    expected_effect: match[3].trim(),
    difficulty: match[4].trim(),
    timing: match[5].trim(),
    auto_executable: match[6].trim() === '可能'
  });
}

// 自動実行可能/手動確認必要に分類
const autoExecutable = proposals.filter(p => p.auto_executable);
const manualRequired = proposals.filter(p => !p.auto_executable);

return [{
  json: {
    report_markdown: report,
    proposals: proposals,
    auto_executable: autoExecutable,
    manual_required: manualRequired,
    generated_at: new Date().toISOString(),
    kpi_data: $('データ整形').item.json
  }
}];
